-- The signed-in user who opened the claim; NULL until it is opened. That user may not settle it.
ALTER TABLE claim ADD COLUMN opened_by VARCHAR(255);
-- The version of a person: starts at 0 and goes up by one each time the person is saved. An edit
-- carries the version its form loaded, and is refused when the person has been saved since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
-- One row per sheet that has stored state of its own. A sheet without a row starts empty.
-- today: the sheet's "today" date; NULL means the real date.
CREATE TABLE sheet (
    id    VARCHAR(100) PRIMARY KEY,
    today DATE
);
-- The people on a sheet, listed in the order they were added (by id).
-- name: as entered, never blank; grade: one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL,
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's name is unique on the sheet, compared without regard to case. Names are stored
-- without surrounding spaces; name_key is the name as compared.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person's claims, listed newest first (by id, descending).
-- amount: 0.00 or more, two decimals; claim_date: defaults to the sheet's today; note: may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)  NOT NULL,
    person_id  BIGINT        NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE          NOT NULL,
    note       VARCHAR(1000) NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The sheet's rate for each grade: a percent with two decimals. A grade without a row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(100)  NOT NULL,
    grade    CHAR(1)       NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0 AND pct <= 100),
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's status: DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID. SETTLED and VOID are final.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
-- A claim's number on its sheet: given when the claim is opened (1, 2, ... with no gaps, never
-- reused), NULL for a draft, and cleared when the claim is voided.
-- last_claim_number: the last number the sheet gave out; 0 before any claim was opened.
ALTER TABLE sheet ADD COLUMN last_claim_number INT DEFAULT 0 NOT NULL;
ALTER TABLE claim ADD COLUMN claim_number INT;
-- A claim's due fixed when it was settled: amount x the person's grade's rate at that moment,
-- rounded half up to two decimals. NULL while the claim is not settled, or when it was settled
-- without a rate, so its due stays live.
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(12, 2);
-- A rate can carry a from-date: a grade may have several rates, each in force from its from-date
-- (NULL: from the beginning of time). One rate per sheet, grade and from-date at most; setting one
-- that exists replaces it.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD CONSTRAINT rate_grade_from UNIQUE NULLS NOT DISTINCT (sheet_id, grade, from_date);
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim made by a person on a sheet. Mutable so an Apply step changes it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private final long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private Integer number;
    private BigDecimal settledDue;
    private String openedBy;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, Integer number, BigDecimal settledDue, String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    /** The claim's number on the sheet: null for a draft or a voided claim. */
    public Integer getNumber() { return number; }
    public void setNumber(Integer number) { this.number = number; }
    /** The due fixed when the claim was settled: null while it is live (not settled, or settled without a rate). */
    public BigDecimal getSettledDue() { return settledDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    /** The user who opened the claim: null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims of each sheet, newest first. */
@Repository
public class ClaimRepository {

    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getString("sheet_id"),
            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(),
            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
            rs.getObject("claim_number", Integer.class), rs.getBigDecimal("settled_due"),
            rs.getString("opened_by"));

    private final JdbcTemplate jdbc;

    public ClaimRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Claim> findBySheet(String sheetId) {
        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY id DESC", ROW, sheetId);
    }

    public Claim findById(String sheetId, long id) {
        List<Claim> found = jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    public Claim create(String sheetId, long personId, BigDecimal amount, LocalDate date, String note) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note) VALUES (?, ?, ?, ?, ?)",
                    new String[] {"id"});
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            return ps;
        }, keys);
        return new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null);
    }

    public void save(Claim claim) {
        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?"
                + " WHERE sheet_id = ? AND id = ?",
                claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
                claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(), claim.getSheetId(), claim.getId());
    }

    /** Gives out the sheet's next claim number. The counter is raised and read in one statement, so
     *  claims opened at the same moment never share a number, and the number is never given again. */
    public int nextNumber(String sheetId) {
        jdbc.update("MERGE INTO sheet (id) KEY (id) VALUES (?)", sheetId);
        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE "
                + "(UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)", Integer.class, sheetId);
    }
}
package net.officefloor.hq.app.claim;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-MM-dd, the status by name,
 *  the number (null when it has none), the due fixed when it was settled (null while it is live),
 *  who opened it (null until it is opened). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        Integer number, String settledDue, String openedBy) {
    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy());
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim the sheet's next number; voiding clears it. Settling fixes the claim's
 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
 *  The user who opened a claim may not settle it (four eyes).
 *  Publishes the number the audit line carries (for a void, the number the claim had). */
public class ApplyClaimAction {
    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimRepository repository,
            PersonRepository people, RateRepository rates, Out<ClaimNumber> numberOut,
            @RequestParam(value = "user", required = false) String user)
            throws InvalidClaimStatusException {
        if (!action.allowedFrom(claim.getStatus())) {
            throw new InvalidClaimStatusException(
                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
        }
        if (action == ClaimAction.SETTLE && claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle it.");
        }
        Integer had = claim.getNumber();
        claim.setStatus(action.to());
        switch (action) {
            case OPEN -> {
                claim.setNumber(repository.nextNumber(claim.getSheetId()));
                claim.setOpenedBy(user);
            }
            case VOID -> claim.setNumber(null);
            case SETTLE -> claim.setSettledDue(dueNow(claim, people, rates));
            default -> { }
        }
        numberOut.set(new ClaimNumber(action == ClaimAction.VOID ? had : claim.getNumber()));
    }

    /** amount × pct / 100, rounded half to even to two decimals; null when no rate is in force on the claim's date. */
    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates) {
        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
        return Rate.inForce(rates.findBySheet(claim.getSheetId()), person.getGrade(), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }
}
